"""Read-only clinical evaluation status, generated by ``python -m research.clinical.publish``."""
from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path
from typing import Any

STATUS_PATH = Path(__file__).with_name("clinical_targets_status.json")


@lru_cache(maxsize=1)
def clinical_status() -> dict[str, Any]:
    return json.loads(STATUS_PATH.read_text(encoding="utf-8"))


def targets_for(age_group: str | None) -> list[dict[str, Any]]:
    """Each target with ``assessable`` resolved for one case's age group (unknown age is never assessable)."""
    return [{**target, "assessable": target["status"] == "activated" and age_group in target["supported_population"]}
            for target in clinical_status()["targets"]]
